/* eslint-disable react/prop-types */
// src/components/SettingsPanel.jsx

import React from 'react';

function SettingsPanel({ onChange }) {
  return (
    <div>
      {/* Заголовок */}
      <h3 className="text-lg font-semibold mb-4">Режим генерации</h3>

      {/* Описание */}
      <p className="mb-6 text-sm">
        Строго следовать правилам музыкальной гармонии?
        <br />
        (Заканчивать кадансом, запрет перехода V -> IV)
      </p>

      {/* Кнопки выбора */}
      <div className="flex flex-col sm:flex-row gap-3">
        {/* Кнопка "Да" - Запретить переход V->IV */}
        <button
          data-action="1"
          onClick={() => onChange('1')}
          className="w-full sm:w-auto bg-blue-500 hover:bg-blue-700 text-white font-medium py-2 px-4 rounded transition-colors"
        >
          Да 📐 Заканчивать кадансом
        </button>

        {/* Кнопка "Нет" - Разрешить переход V->IV */}
        <button
          data-action="2"
          onClick={() => onChange('2')}
          className="w-full sm:w-auto bg-gray-700 hover:bg-gray-600 text-white font-medium py-2 px-4 rounded transition-colors"
        >
          Нет 🎨 Свободная генерация
        </button>
      </div>
    </div>
  );
}

export default SettingsPanel;
